-- ---------------------------------------------------------------- приёмы
insert into public.techniques (id, name, energy, phases, tags, size_min, size_max, levels, goal, description, how_to) values
  ('p01', 'Да-нетка', 3, array['start']::text[], array['понятие','абстракция','доказательство']::text[], 5, 35, array['low','mid','high']::text[],
   'Ввести новое понятие через сужение гипотез',
   'Учитель загадывает объект (число, фигуру, функцию), класс задаёт вопросы, на которые можно ответить только «да» или «нет».',
   'Загадайте объект по теме и дайте классу 7–10 вопросов. Запрещайте вопрос «а что это?» — он заставляет угадывать, а не рассуждать. В конце попросите назвать признак, который оказался решающим: это и есть определение, к которому вы ведёте урок.'),
  ('p02', 'Лови ошибку', 3, array['start','middle','end']::text[], array['ошибкоопасная','алгоритм','формула','вычисления']::text[], 5, 35, array['low','mid','high']::text[],
   'Сделать типичную ошибку видимой и обсуждаемой',
   'Учитель намеренно решает задание с ошибкой (или раздаёт готовое «чужое» решение), задача класса — найти и объяснить сбой.',
   'Подготовьте 3–4 решения, в двух из них спрячьте типичные для темы ошибки. Ученики работают в парах и отмечают строку, где решение «сломалось». Важно требовать формулировку «нарушено правило …», а не просто «тут неверно».'),
  ('p03', 'Светофор', 2, array['middle','end']::text[], array['вычисления','формула','алгоритм','ошибкоопасная']::text[], 5, 35, array['low','mid']::text[],
   'Мгновенная обратная связь без шума',
   'У каждого ученика три карточки (зелёная/жёлтая/красная). После каждого шага он показывает, понял ли материал.',
   'Разбейте объяснение на 4–5 микрошагов, после каждого — сигнал. Красные карточки — сигнал остановиться и переобъяснить, а не продолжать. Приём почти не производит шума, поэтому хорошо гасит перевозбуждённый класс.'),
  ('p04', 'Билет на выход', 1, array['end']::text[], array['вычисления','понятие','алгоритм','формула','ошибкоопасная']::text[], 5, 35, array['low','mid','high']::text[],
   'Диагностика усвоения за 3 минуты',
   'За 3–5 минут до звонка каждый на маленьком листке отвечает на 1–2 вопроса и сдаёт его на выходе.',
   'Вопросы двух типов: одно короткое задание на применение и один вопрос «что осталось непонятным». Проверьте стопку до следующего урока — она даёт готовый план повторения.'),
  ('p05', 'Три предложения', 1, array['end']::text[], array['понятие','абстракция','доказательство']::text[], 5, 35, array['mid','high']::text[],
   'Свернуть содержание урока в связный текст',
   'Ученик передаёт содержание урока ровно тремя предложениями — ни больше, ни меньше.',
   'Дайте 3 минуты на запись, затем послушайте 3–4 варианта и вместе выберите самый точный. Ограничение объёма заставляет отделять главное от примеров.'),
  ('p06', 'Математическая эстафета', 5, array['middle']::text[], array['вычисления','алгоритм','формула']::text[], 15, 35, array['low','mid']::text[],
   'Отработка техники на скорости',
   'Команды по рядам по очереди выходят к доске, каждый выполняет один шаг цепочки заданий.',
   'Заготовьте 3 колонки по 6–8 однотипных заданий. Следующий участник стартует только после того, как предыдущий сел. Приём очень энергичный — ставьте его в середину и обязательно закрывайте урок тихим приёмом.'),
  ('p07', 'Цепочка вычислений', 4, array['start','middle']::text[], array['вычисления','алгоритм']::text[], 5, 35, array['low','mid']::text[],
   'Разогреть вычислительный навык',
   'Устный счёт по цепочке: ответ предыдущего ученика становится входом для следующего.',
   '8–12 звеньев, темп — примерно 10 секунд на звено. Если цепочка рвётся, класс хором восстанавливает шаг. Хорошо работает как вход в урок после перемены.'),
  ('p08', 'Взаимоопрос в парах', 3, array['middle']::text[], array['формула','понятие','алгоритм']::text[], 5, 35, array['low','mid','high']::text[],
   'Проговорить правила вслух',
   'Ученики в парах по очереди задают друг другу вопросы по карточке и оценивают ответы.',
   'Раздайте парам одинаковый список из 5 вопросов и критерий («полный ответ = формулировка + пример»). Через 4 минуты меняйте роли. Собирать ответы не нужно — ценность в проговаривании.'),
  ('p09', 'Жокей и лошадь', 5, array['start','middle']::text[], array['формула','вычисления','понятие']::text[], 15, 35, array['low','mid']::text[],
   'Соотнести объект и его характеристику через движение',
   'Половина класса получает карточки-задания, половина — карточки-ответы; надо найти свою пару, перемещаясь по кабинету.',
   'Число карточек должно точно совпадать с числом учеников, иначе кто-то останется без пары. Отведите ровно 3 минуты и заранее договоритесь о сигнале тишины. Приём даёт всплеск энергии — не ставьте его в конец урока.'),
  ('p10', 'Найди пару (на парте)', 2, array['middle','end']::text[], array['формула','понятие','вычисления']::text[], 5, 35, array['low','mid']::text[],
   'То же соотнесение, но в тихом варианте',
   'Набор карточек раскладывается на парте, пара учеников молча собирает соответствия.',
   '12–16 карточек на пару: выражение — результат, чертёж — признак, функция — график. Проверка общая: на доске выводится правильная раскладка. Это «тихий двойник» приёма «Жокей и лошадь» для шумных классов.'),
  ('p11', 'Кластер', 2, array['start','end']::text[], array['понятие','абстракция','формула','геометрия']::text[], 5, 35, array['mid','high']::text[],
   'Собрать связи темы в схему',
   'Ключевое понятие в центре, от него — ветви со свойствами, формулами, примерами и связями.',
   'В начале урока кластер строится по памяти и остаётся неполным, в конце — дополняется другим цветом. Разница между двумя состояниями схемы и есть видимый результат урока.'),
  ('p12', 'Фишбоун', 2, array['middle','end']::text[], array['текстовая-задача','доказательство','практика']::text[], 5, 35, array['mid','high']::text[],
   'Разобрать структуру сложной задачи',
   '«Скелет рыбы»: голова — вопрос задачи, верхние кости — данные, нижние — следствия, хвост — вывод.',
   'Возьмите одну многошаговую задачу и разбирайте её схемой на доске вместе с классом. Вторую задачу того же типа ученики раскладывают сами. Приём особенно хорош там, где дети «не видят», с чего начать.'),
  ('p13', 'Мозговой штурм', 4, array['start']::text[], array['понятие','абстракция','доказательство','практика']::text[], 5, 35, array['mid','high']::text[],
   'Набрать гипотезы до объяснения',
   'Класс за короткое время выдаёт максимум идей решения, критика запрещена.',
   'Сформулируйте вопрос, у которого нет одного очевидного ответа, и фиксируйте все версии на доске без оценки. Разбор гипотез — уже следующий этап урока: тогда появляется естественная потребность в новом правиле.'),
  ('p14', 'Проблемная ситуация', 3, array['start']::text[], array['понятие','абстракция','ошибкоопасная','доказательство']::text[], 5, 35, array['mid','high']::text[],
   'Создать разрыв между знанием и задачей',
   'Задание, которое старыми средствами решается неудобно или не решается вовсе.',
   'Дайте задачу, где прежний способ буксует (например, уравнение, которое не решается подбором). Дайте классу упереться 2–3 минуты — именно это делает новое правило нужным, а не «ещё одним параграфом».'),
  ('p15', 'Своя опора', 1, array['middle','end']::text[], array['формула','алгоритм','абстракция']::text[], 5, 35, array['low','mid','high']::text[],
   'Свернуть правило в личный конспект',
   'Каждый ученик делает свой опорный конспект темы на половине листа: формулы, схема, один пример.',
   'Жёстко ограничьте размер листа — это заставляет отбирать существенное. Разрешите пользоваться опорой на следующем уроке: тогда её делают всерьёз. Приём тихий и хорошо закрывает урок.'),
  ('p16', 'Толстые и тонкие вопросы', 2, array['middle','end']::text[], array['понятие','доказательство','абстракция']::text[], 5, 35, array['mid','high']::text[],
   'Разделить воспроизведение и понимание',
   'Ученики сами составляют «тонкие» вопросы (кто? что? как называется?) и «толстые» (почему? а если изменить?).',
   'Норма — 3 тонких и 2 толстых вопроса на пару. Затем пары обмениваются листами и отвечают. Толстые вопросы учеников — хороший материал для начала следующего урока.'),
  ('p17', 'Аквариум', 3, array['middle']::text[], array['доказательство','текстовая-задача','абстракция']::text[], 5, 25, array['mid','high']::text[],
   'Сделать ход рассуждения наблюдаемым',
   'Малая группа решает задачу вслух в центре класса, остальные наблюдают за ходом рассуждения и затем комментируют.',
   'Дайте наблюдателям конкретный фокус: «отметьте момент, где группа выбрала способ». Обсуждение ведите про процесс, а не про правильность ответа. В классе больше 25 человек внешний круг рассыпается — приём лучше не брать.'),
  ('p18', 'Снежный ком', 4, array['start']::text[], array['понятие','формула','вычисления']::text[], 5, 35, array['low','mid']::text[],
   'Быстро поднять из памяти всё, что класс уже знает',
   'Первый ученик называет один факт по теме, следующий повторяет его и добавляет свой, и так по нарастающей.',
   'Держите список на доске — иначе цепочка рвётся на шестом шаге. Оптимально 8–10 звеньев. Приём разгоняет сонный класс, но шумный им лучше не открывать.'),
  ('p19', 'Математическое лото', 3, array['middle']::text[], array['вычисления','формула','алгоритм']::text[], 5, 35, array['low','mid']::text[],
   'Массовая отработка с самопроверкой',
   'Ученики решают задания и закрывают карточками клетки своего поля; из карточек складывается картинка или слово.',
   'Заготовьте поле на 9–12 заданий. Самопроверка встроена: если картинка не сложилась, где-то ошибка — ученик ищет её сам. Экономит время учителя на проверке.'),
  ('p20', 'Ранжирование', 2, array['middle','end']::text[], array['доказательство','понятие','алгоритм']::text[], 5, 35, array['mid','high']::text[],
   'Заставить сравнивать, а не просто решать',
   'Набор утверждений или задач нужно расставить по порядку: от верного к неверному, от простого к сложному, по порядку шагов.',
   'Дайте 6–8 карточек и обязательное требование объяснить границу: «почему эта задача сложнее соседней». Спор о порядке ценнее итогового списка.'),
  ('p21', 'Верю — не верю', 3, array['start']::text[], array['ошибкоопасная','понятие','формула']::text[], 5, 35, array['low','mid']::text[],
   'Вскрыть ложные убеждения до объяснения',
   'Учитель зачитывает утверждения по теме, ученики сигналят, верят они или нет, и коротко объясняют.',
   '6–8 утверждений, среди них обязательно 2–3 правдоподобных, но ложных. Ответы не комментируйте сразу — вернитесь к спорным в конце урока, когда появится инструмент для проверки.'),
  ('p22', 'Графический диктант', 2, array['start','end']::text[], array['формула','понятие','вычисления','ошибкоопасная']::text[], 5, 35, array['low','mid']::text[],
   'Тихая фронтальная проверка за 5 минут',
   'На каждое утверждение ученик рисует «˄» (согласен) или «_» (не согласен); получается ломаная, которую легко сверить с эталоном.',
   '10 утверждений, темп — одно в 20 секунд. Проверка мгновенная: эталонная ломаная выводится на доску. Ученик сразу видит, на каком пункте разошёлся.'),
  ('p23', 'Карусель (станции)', 5, array['middle']::text[], array['вычисления','алгоритм','практика','геометрия']::text[], 15, 35, array['mid','high']::text[],
   'Пройти несколько типов заданий за урок',
   'По кабинету расставлены 4–5 станций с разными типами заданий, группы переходят от станции к станции по сигналу.',
   'Жёсткий тайминг: 5 минут на станцию, сигнал — общий для всех. На каждой станции — лист ответов группы. Приём даёт максимум движения, поэтому требует заранее оговорённых правил перехода.'),
  ('p24', 'Кубик Блума', 3, array['middle','end']::text[], array['понятие','абстракция','практика']::text[], 5, 35, array['mid','high']::text[],
   'Задать вопросы разного уровня',
   'На гранях кубика: назови, объясни, почему, предложи, придумай, поделись. Ученик бросает кубик и отвечает по выпавшей грани.',
   'Сформулируйте одну тему и пустите кубик по рядам. Грани «придумай» и «предложи» дают самые интересные ответы — не пропускайте их ради экономии времени.'),
  ('p25', 'Составь задачу', 2, array['end']::text[], array['текстовая-задача','практика','понятие']::text[], 5, 35, array['mid','high']::text[],
   'Переход от решения к конструированию',
   'Ученик сам придумывает задачу по изученной теме с заданными ограничениями и решает её.',
   'Задайте рамку: «задача в 2 действия, ответ — целое число, сюжет из жизни школы». Лучшие задачи возьмите в домашнюю работу — это сильная мотивация.'),
